#include <iostream>
#include <string>
using namespace std;

class Animal {
protected:
    string name;
public:
    Animal(string n) : name(n) {}
    virtual void speak() const = 0;
    void showName() const {
        cout << "本喵叫 " << name << endl;
    }
};

class Kitten : public Animal {
    int fish;
public:
    Kitten(string n, int f) : Animal(n), fish(f) {}
    void speak() const override {
        cout << name << "：喵～本喵吃了 " << fish << " 条" << endl;
    }
};

int main() {
    int f = 0;
    cin >> f;

    Kitten k("{catName}", f);
    Animal& r = k;
    r.showName();
    r.speak();
    return 0;
}
